<template>
    <Card :title="cardTitle" icon="forum" card-header-class="card-header-rose">
        <p v-if="loading" role="status">Ielādē komentārus…</p>
        <p v-else-if="loadError" class="text-danger" role="alert">{{ loadError }}</p>
        <p v-else-if="!comments.length">Vēl nav komentāru.</p>

        <ul v-if="comments.length" class="list-unstyled d-flex flex-column gap-3 mb-0" role="list">
            <li v-for="comment in comments" :key="comment.id" class="d-flex align-items-start gap-2">
                <span class="comment-avatar rounded-circle d-grid flex-shrink-0" aria-hidden="true">
                    <i class="material-icons">person</i>
                </span>
                <div class="comment-message flex-grow-1">
                    <strong class="d-block fw-medium">{{ comment.user?.name ?? 'Nezināms lietotājs' }}</strong>
                    <small class="comment-date d-block">{{ comment.created_at }}</small>
                    <p class="mt-1 mb-0">{{ comment.comment }}</p>
                </div>
            </li>
        </ul>

        <form class="comment-composer mt-3" @submit.prevent="submitComment">
            <div class="d-flex align-items-center gap-2">
                <input
                    v-model="commentInput"
                    type="text"
                    name="comment"
                    class="form-control flex-grow-1"
                    :placeholder="label"
                    :aria-label="label"
                    :disabled="submitting"
                    autocomplete="off"
                />
                <button
                    type="submit"
                    class="btn btn-rose btn-round btn-fab btn-sm flex-shrink-0 m-0"
                    aria-label="Nosūtīt komentāru"
                    :disabled="loading || submitting || !commentInput.trim()"
                >
                    <i class="material-icons" aria-hidden="true">send</i>
                </button>
            </div>
            <p v-if="submitError" class="text-danger mb-0" role="alert">{{ submitError }}</p>
        </form>
    </Card>
</template>

<script>
import axios from 'axios';
import Card from './Card.vue';

export default {
    name: 'CommentCard',
    components: { Card },
    props: {
        cardTitle: { type: String, default: 'Komentāri' },
        label: { type: String, default: 'Tavs komentārs...' },
        listUrl: { type: String, required: true },
        storeUrl: { type: String, required: true },
    },
    data() {
        return {
            comments: [],
            commentInput: '',
            loading: true,
            submitting: false,
            loadError: '',
            submitError: '',
        };
    },
    mounted() {
        this.fetchComments();
    },
    methods: {
        async fetchComments() {
            this.loading = true;
            this.loadError = '';

            try {
                const { data } = await axios.get(this.listUrl);
                this.comments = data;
            } catch {
                this.loadError = 'Neizdevās ielādēt komentārus.';
            } finally {
                this.loading = false;
            }
        },
        async submitComment() {
            const comment = this.commentInput.trim();
            if (this.loading || this.submitting || !comment) {
                return;
            }

            this.submitting = true;
            this.submitError = '';

            try {
                const { data } = await axios.post(this.storeUrl, { comment });
                this.comments.push(data);
                this.commentInput = '';
            } catch (error) {
                this.submitError = error.response?.data?.errors?.comment?.[0]
                    ?? 'Neizdevās pievienot komentāru.';
            } finally {
                this.submitting = false;
            }
        },
    },
};
</script>

<style scoped>
.comment-avatar {
    inline-size: 2rem;
    block-size: 2rem;
    place-items: center;
    background: var(--bg-3);
    color: var(--fg-2);
}

.comment-avatar .material-icons {
    font-size: 1.125rem;
}

.comment-message {
    min-inline-size: 0;
    padding: .625rem .75rem;
    border-radius: .25rem .75rem .75rem;
    background: light-dark(#f4f4f4, var(--bg-3));
    overflow-wrap: anywhere;
}

.comment-date {
    color: var(--fg-2);
}

.comment-composer .form-control {
    min-inline-size: 0;
}
</style>
